import AppKit

/// Help > Keyboard Shortcuts. The menu-bar part is generated by walking the
/// live main menu, so it cannot drift from what the app actually binds; only
/// keys handled outside the menu are listed by hand in `extras`.
///
/// Rows are `name <tab> shortcut` with the shortcut right-aligned. The content
/// never wraps: it is as wide as the window, but no narrower than its widest
/// row, below which the window scrolls horizontally instead.
final class ShortcutsWindowController: NSWindowController, NSWindowDelegate {
    /// Bindings that are not menu items (key monitor, find bar, search panel).
    private static let extras: [(section: String, rows: [(String, String)])] = [
        ("Tabs", [("Next Tab", "⌃⇥"), ("Previous Tab", "⌃⇧⇥")]),
        ("In the All Tabs Switcher", [
            ("Filter", "Type"), ("Move Between Tabs", "↑ ↓  ⌃⇥"), ("Switch to Tab", "↩"), ("Close", "⎋"),
        ]),
        ("In the Find Bar", [
            ("Next Match", "↩"), ("Previous Match", "⇧↩"), ("Close Find Bar", "⎋"),
        ]),
        ("In Search All Tabs", [
            ("Open Selected Result", "↩"), ("Move Between Results", "↑ ↓"), ("Close", "⎋"),
        ]),
        ("Links and Files", [
            ("Open a Linked Document in a New Tab", "Click"),
            ("Open a Dropped File", "Drop on window"),
        ]),
    ]

    /// Items AppKit injects into the Edit menu itself; not Xem's commands.
    private static let systemTitles: Set<String> = [
        "Writing Tools", "AutoFill", "Start Dictation…", "Emoji & Symbols",
    ]

    private static let inset = NSSize(width: 16, height: 14)
    /// Space kept between a row's name and its shortcut.
    private static let gutter: CGFloat = 32

    private let textView = NSTextView()
    private let scroll = NSScrollView()
    private var rows: [(kind: Kind, name: String, shortcut: String)] = []

    private enum Kind { case header, row }

    init() {
        let window = PopupWindow(
            contentRect: NSRect(x: 0, y: 0, width: 520, height: 560),
            styleMask: [.titled, .closable, .resizable],
            backing: .buffered,
            defer: false
        )
        window.title = "Keyboard Shortcuts"
        window.isReleasedWhenClosed = false
        window.tabbingMode = .disallowed
        window.minSize = NSSize(width: 280, height: 240)
        super.init(window: window)
        window.delegate = self

        textView.isEditable = false
        textView.drawsBackground = false
        textView.textContainerInset = Self.inset
        // No wrapping: width is set explicitly in `layoutContent`.
        textView.isHorizontallyResizable = true
        textView.isVerticallyResizable = true
        textView.autoresizingMask = []
        textView.textContainer?.widthTracksTextView = false
        textView.textContainer?.heightTracksTextView = false

        scroll.documentView = textView
        scroll.hasVerticalScroller = true
        scroll.hasHorizontalScroller = true
        scroll.autohidesScrollers = true
        scroll.drawsBackground = false
        window.contentView = scroll

        NotificationCenter.default.addObserver(
            forName: UIFontSize.didChange, object: nil, queue: .main
        ) { [weak self] _ in self?.layoutContent() }
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) { fatalError("not supported") }

    func showAndFocus() {
        // Rebuilt each time: menu titles change ("Show/Hide Outline").
        rows = Self.collectRows()
        layoutContent()
        window?.center(over: NSApp.keyWindow)
        showWindow(nil)
        window?.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }

    func windowDidResize(_ notification: Notification) {
        layoutContent()
    }

    // MARK: Layout

    private func layoutContent() {
        guard !rows.isEmpty else { return }
        let bodyFont = UIFontSize.font()
        let keyFont = UIFontSize.monospaced(NSFont.systemFontSize - 1)
        let headerFont = UIFontSize.font(NSFont.systemFontSize + 1, weight: .bold)

        // Narrowest the content may get: the widest row plus a gutter.
        var widest: CGFloat = 0
        for row in rows where row.kind == .row {
            let name = (row.name as NSString).size(withAttributes: [.font: bodyFont]).width
            let key = (row.shortcut as NSString).size(withAttributes: [.font: keyFont]).width
            widest = max(widest, name + Self.gutter + key)
        }
        // lineFragmentPadding (5) on each side of the text container.
        let minWidth = ceil(widest + 2 * Self.inset.width + 10)
        let visible = scroll.contentSize.width
        let width = max(minWidth, visible)
        let tabStop = width - 2 * Self.inset.width - 10

        let rowStyle = NSMutableParagraphStyle()
        rowStyle.tabStops = [NSTextTab(textAlignment: .right, location: tabStop)]
        rowStyle.lineBreakMode = .byClipping
        rowStyle.paragraphSpacing = 3
        let headerStyle = NSMutableParagraphStyle()
        headerStyle.paragraphSpacingBefore = 14
        headerStyle.paragraphSpacing = 4
        headerStyle.lineBreakMode = .byClipping

        let out = NSMutableAttributedString()
        for row in rows {
            switch row.kind {
            case .header:
                out.append(NSAttributedString(string: row.name + "\n", attributes: [
                    .font: headerFont, .foregroundColor: NSColor.labelColor, .paragraphStyle: headerStyle,
                ]))
            case .row:
                out.append(NSAttributedString(string: row.name, attributes: [
                    .font: bodyFont, .foregroundColor: NSColor.labelColor, .paragraphStyle: rowStyle,
                ]))
                out.append(NSAttributedString(string: "\t" + row.shortcut + "\n", attributes: [
                    .font: keyFont, .foregroundColor: NSColor.secondaryLabelColor, .paragraphStyle: rowStyle,
                ]))
            }
        }
        textView.textStorage?.setAttributedString(out)

        guard let container = textView.textContainer, let layout = textView.layoutManager else { return }
        container.containerSize = NSSize(
            width: width - 2 * Self.inset.width, height: .greatestFiniteMagnitude)
        layout.ensureLayout(for: container)
        let used = layout.usedRect(for: container)
        let height = ceil(used.height + 2 * Self.inset.height)
        textView.setFrameSize(NSSize(width: width, height: max(height, scroll.contentSize.height)))
    }

    // MARK: Content

    private static func collectRows() -> [(kind: Kind, name: String, shortcut: String)] {
        var rows: [(kind: Kind, name: String, shortcut: String)] = []
        for (title, items) in menuSections() where !items.isEmpty {
            rows.append((.header, title, ""))
            rows += items.map { (.row, $0.0, $0.1) }
        }
        for extra in extras {
            rows.append((.header, extra.section, ""))
            rows += extra.rows.map { (.row, $0.0, $0.1) }
        }
        return rows
    }

    /// Every titled item in the main menu, grouped by top-level menu.
    private static func menuSections() -> [(String, [(String, String)])] {
        guard let main = NSApp.mainMenu else { return [] }
        var sections: [(String, [(String, String)])] = []
        for top in main.items {
            guard let submenu = top.submenu else { continue }
            var rows: [(String, String)] = []
            for item in submenu.items
            where !item.isSeparatorItem && !item.isHidden && !item.isAlternate
                && item.action != nil && !systemTitles.contains(item.title)
            {
                // AppKit appends one private-action item per open window.
                if let action = item.action, NSStringFromSelector(action).hasPrefix("_") { continue }
                rows.append((item.title, shortcut(for: item)))
            }
            let title = submenu.title.isEmpty ? "Xem" : submenu.title
            sections.append((title, rows))
        }
        return sections
    }

    private static func shortcut(for item: NSMenuItem) -> String {
        // AppKit replaces this item with its own, whose key equivalent carries
        // no modifiers (the system draws Ctrl-Cmd-F itself).
        if item.action == #selector(NSWindow.toggleFullScreen(_:)) { return "⌃⌘F" }
        guard let first = item.keyEquivalent.unicodeScalars.first else { return "" }
        var mods = item.keyEquivalentModifierMask
        let key: String
        switch Int(first.value) {
        case NSLeftArrowFunctionKey: key = "←"
        case NSRightArrowFunctionKey: key = "→"
        case NSUpArrowFunctionKey: key = "↑"
        case NSDownArrowFunctionKey: key = "↓"
        case 9: key = "⇥"
        case 13, 3: key = "↩"
        case 27: key = "⎋"
        case 32: key = "Space"
        case 8, 0x7F: key = "⌫"
        default:
            let text = item.keyEquivalent
            // An uppercase key equivalent means Shift is held.
            if text != text.lowercased() { mods.insert(.shift) }
            key = text.uppercased()
        }
        var symbols = ""
        if mods.contains(.control) { symbols += "⌃" }
        if mods.contains(.option) { symbols += "⌥" }
        if mods.contains(.shift) { symbols += "⇧" }
        if mods.contains(.command) { symbols += "⌘" }
        return symbols + key
    }
}
